      styles: [".promo-section[_ngcontent-%COMP%] {\n  padding: 24px 0;\n  max-width: 820px;\n}\n\n.promo-title[_ngcontent-%COMP%] {\n  font-size: 20px;\n  font-weight: 700;\n  color: var(--color-secondary);\n  margin-bottom: 20px;\n}\n\n.promo-form-card[_ngcontent-%COMP%], \n.promo-list-card[_ngcontent-%COMP%] {\n  background: #fff;\n  border: 1px solid #e8edf2;\n  border-radius: 10px;\n  padding: 20px 24px;\n  margin-bottom: 20px;\n  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);\n}\n\n.promo-form-title[_ngcontent-%COMP%] {\n  font-size: 15px;\n  font-weight: 700;\n  color: var(--color-secondary);\n  margin: 0 0 16px;\n}\n\n.promo-form-grid[_ngcontent-%COMP%] {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 14px;\n}\n@media (max-width: 540px) {\n  .promo-form-grid[_ngcontent-%COMP%] {\n    grid-template-columns: 1fr;\n  }\n}\n\n.promo-field[_ngcontent-%COMP%] {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.promo-field--full[_ngcontent-%COMP%] {\n  grid-column: 1/-1;\n}\n\n.promo-label[_ngcontent-%COMP%] {\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--color-secondary);\n}\n.promo-label[_ngcontent-%COMP%]   .req[_ngcontent-%COMP%] {\n  color: #e74c3c;\n}\n\n.promo-input[_ngcontent-%COMP%], \n.promo-select[_ngcontent-%COMP%] {\n  padding: 8px 10px;\n  border: 1px solid #ced4da;\n  border-radius: 6px;\n  font-size: 14px;\n  font-family: inherit;\n  outline: none;\n  background: #fff;\n  transition: border-color 0.15s;\n}\n.promo-input[_ngcontent-%COMP%]:focus, \n.promo-select[_ngcontent-%COMP%]:focus {\n  border-color: var(--color-primary-dark);\n}\n\n.promo-input--upper[_ngcontent-%COMP%] {\n  text-transform: uppercase;\n}\n\n.promo-form-actions[_ngcontent-%COMP%] {\n  margin-top: 16px;\n  display: flex;\n  justify-content: flex-end;\n}\n\n.promo-btn[_ngcontent-%COMP%] {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  border: none;\n  border-radius: 6px;\n  font-size: 13px;\n  font-weight: 600;\n  cursor: pointer;\n  padding: 8px 16px;\n  transition: background 0.15s;\n}\n.promo-btn--save[_ngcontent-%COMP%] {\n  background: var(--color-primary-dark);\n  color: #fff;\n}\n.promo-btn--save[_ngcontent-%COMP%]:hover:not(:disabled) {\n  background: #117a65;\n}\n.promo-btn--save[_ngcontent-%COMP%]:disabled {\n  background: #b2bec3;\n  cursor: not-allowed;\n}\n.promo-btn--delete[_ngcontent-%COMP%] {\n  background: none;\n  border: 1px solid #e0e6ed;\n  color: #8a9ab0;\n  padding: 6px 10px;\n}\n.promo-btn--delete[_ngcontent-%COMP%]:hover {\n  border-color: #e74c3c;\n  color: #e74c3c;\n}\n.promo-btn--danger-sm[_ngcontent-%COMP%] {\n  background: #e74c3c;\n  color: #fff;\n  padding: 5px 12px;\n  font-size: 12px;\n}\n.promo-btn--danger-sm[_ngcontent-%COMP%]:hover {\n  background: #c0392b;\n}\n.promo-btn--neutral-sm[_ngcontent-%COMP%] {\n  background: #f0f2f5;\n  color: var(--color-secondary);\n  padding: 5px 12px;\n  font-size: 12px;\n}\n.promo-btn--neutral-sm[_ngcontent-%COMP%]:hover {\n  background: #dde1e7;\n}\n\n.promo-empty[_ngcontent-%COMP%] {\n  color: #8a9ab0;\n  font-size: 13px;\n  font-style: italic;\n}\n\n.promo-row[_ngcontent-%COMP%] {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 12px 0;\n  border-bottom: 1px solid #f0f2f5;\n  border-left: 3px solid #dee2e6;\n  padding-left: 12px;\n}\n.promo-row[_ngcontent-%COMP%]:last-child {\n  border-bottom: none;\n}\n.promo-row--active[_ngcontent-%COMP%] {\n  border-left-color: var(--color-primary-dark);\n}\n.promo-row--expired[_ngcontent-%COMP%] {\n  border-left-color: #bdc3c7;\n  opacity: 0.65;\n}\n\n.promo-row-main[_ngcontent-%COMP%] {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  flex-wrap: wrap;\n  flex: 1;\n}\n\n.promo-code-badge[_ngcontent-%COMP%] {\n  font-family: monospace;\n  font-size: 14px;\n  font-weight: 700;\n  background: #f0faf7;\n  color: #0e6655;\n  padding: 2px 8px;\n  border-radius: 6px;\n  letter-spacing: 1px;\n}\n\n.promo-discount[_ngcontent-%COMP%] {\n  font-size: 14px;\n  font-weight: 700;\n  color: var(--color-primary-dark);\n}\n\n.promo-cat[_ngcontent-%COMP%] {\n  font-size: 13px;\n  color: var(--color-secondary);\n}\n\n.promo-dates[_ngcontent-%COMP%] {\n  font-size: 12px;\n  color: #8a9ab0;\n}\n\n.promo-status-badge[_ngcontent-%COMP%] {\n  font-size: 11px;\n  font-weight: 700;\n  padding: 2px 8px;\n  border-radius: 10px;\n}\n.promo-status-badge.promo-status--active[_ngcontent-%COMP%] {\n  background: #e8f8f5;\n  color: var(--color-primary-dark);\n}\n.promo-status-badge.promo-status--upcoming[_ngcontent-%COMP%] {\n  background: #fef9e7;\n  color: #b7950b;\n}\n.promo-status-badge.promo-status--expired[_ngcontent-%COMP%] {\n  background: #f4f4f4;\n  color: #8a9ab0;\n}\n\n.promo-confirm-delete[_ngcontent-%COMP%] {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 12px;\n  color: #e74c3c;\n}\n/*# sourceMappingURL=data:application/json;charset=utf-8;base64, */"],
